/** The record, its pinned native tree, the templates and the clips. */
export function heraldNative(r,n){
 const spec=SPECS[r?.prefabKey];
 if(!spec||r.key!==r.prefabKey||r.level!==0||r.notCountInTotal||r.applyWay!==spec.applyWay||Object.entries(spec.stats).some(([k,v])=>!same(r.stats[k],v))
  ||!same(r.abilities,spec.abilities)||!same(r.talents,spec.talents)||!same(r.skills,spec.skills))return false;
 if(!same(closure(n),spec.components)||Object.entries(TEMPLATES).some(([k,v])=>!same(n.$template(k),v)))return false;
 const root=n[r.prefabKey]?.find(v=>"_modes"in v),graphic=n.$ref(root?._animator),clock=clocks.enemies[r.prefabKey];
 return !!clock&&n.$ref(graphic?._skeleton)?.skeletonDataAsset?.m_PathID===clock.source?.skeletonDataPathId
  &&Object.entries(CLOCK.durations).every(([k,v])=>clock.durations[k]===v)
  &&Object.entries(CLOCK.events).every(([k,v])=>same(clock.events[k]?.filter(x=>x.name==="OnAttack").map(x=>x.time),v));
}
